    "content": "import jwt from 'jsonwebtoken';

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-key';
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const MAX_ATTEMPTS = 5;

const failedAttempts = new Map(); // email → {count, resetTime}

export const rateLimiter = (req, res, next) => {
  const email = req.body.email?.toLowerCase();
  if (!email) return next();

  const record = failedAttempts.get(email);
  const now = Date.now();

  if (record && now < record.resetTime) {
    if (record.count >= MAX_ATTEMPTS) {
      return res.status(429).json({ error: 'Too many login attempts. Try again in 15 minutes.' });
    }
  } else {
    failedAttempts.set(email, { count: 0, resetTime: now + RATE_LIMIT_WINDOW });
  }

  req.trackLoginAttempt = () => {
    const record = failedAttempts.get(email) || { count: 0, resetTime: now + RATE_LIMIT_WINDOW };
    record.count++;
    failedAttempts.set(email, record);
  };

  req.clearLoginAttempts = () => {
    failedAttempts.delete(email);
  };

  next();
};

export const issueToken = (userId, email) => {
  return jwt.sign({ userId, email }, JWT_SECRET, { expiresIn: '7d' });
};

export const verifyToken = (token) => {
  try {
    return jwt.verify(token, JWT_SECRET);
  } catch {
    return null;
  }
};

export const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token provided' });

  const payload = verifyToken(token);
  if (!payload) return res.status(401).json({ error: 'Invalid token' });

  req.user = payload;
  next();
};
