    "content": "import express from 'express';
import bcrypt from 'bcrypt';
import { createUser, getUserByEmail } from './db.js';
import { rateLimiter, issueToken, verifyToken } from './middleware.js';

const router = express.Router();

router.post('/signup', async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ error: 'Email and password required' });
    }

    if (password.length < 8) {
      return res.status(400).json({ error: 'Password must be at least 8 characters' });
    }

    const existing = await getUserByEmail(email.toLowerCase());
    if (existing) {
      return res.status(409).json({ error: 'Email already registered' });
    }

    const passwordHash = await bcrypt.hash(password, 10);
    await createUser(email.toLowerCase(), passwordHash);

    res.status(201).json({ message: 'User created. Please log in.' });
  } catch (err) {
    res.status(500).json({ error: 'Signup failed' });
  }
});

router.post('/login', rateLimiter, async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ error: 'Email and password required' });
    }

    const user = await getUserByEmail(email.toLowerCase());
    if (!user) {
      req.trackLoginAttempt();
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const match = await bcrypt.compare(password, user.password_hash);
    if (!match) {
      req.trackLoginAttempt();
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    req.clearLoginAttempts();
    const token = issueToken(user.id, user.email);
    res.json({ token, email: user.email });
  } catch (err) {
    res.status(500).json({ error: 'Login failed' });
  }
});

router.post('/verify', (req, res) => {
  const { token } = req.body;
  if (!token) return res.status(400).json({ error: 'Token required' });

  const payload = verifyToken(token);
  if (!payload) return res.status(401).json({ error: 'Invalid or expired token' });

  res.json({ valid: true, user: payload });
});

export default router;
